#!/usr/bin/env python3
"""Prepend legal-review banner to docs/LICENSES.md if missing."""

from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PATH = ROOT / "docs" / "LICENSES.md"
BANNER = """# Third-party licence listing

**Flag for legal review.** This table is generated by `pip-licenses` from the active
venv. It is **not** a legal conclusion. SegGPT/Painter weights were trained on
third-party datasets; redistribution of weights/models may need separate review.
PerSAM is MIT; Segment Anything is Apache-2.0.

Generated by: `make licenses`

---

"""


def main() -> None:
    body = PATH.read_text(encoding="utf-8") if PATH.is_file() else ""
    if body.startswith("# Third-party licence listing"):
        return
    PATH.write_text(BANNER + body, encoding="utf-8")


if __name__ == "__main__":
    main()
